describe('Print Filtered Table View', () => {
  beforeEach(() => {
    cy.visit('/table-view');
  });

  it('should print a filtered table view with valid filters', () => {
    // Setup: Apply filters to table
    cy.get('[data-testid="filter-input-name"]').type('John');
    cy.get('[data-testid="filter-input-age"]').type('30');
    cy.get('[data-testid="apply-filters-btn"]').click();

    // Verify filters are applied
    cy.get('[data-testid="filter-status"]').should('contain', 'Active');
    cy.get('[data-testid="filter-status"]').should('contain', 'Inactive');

    // Verify table is filtered
    cy.get('[data-testid="table-row"]').should('have.length', 2);
    cy.get('[data-testid="table-row"]').first().should('contain', 'John');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Jane');

    // Verify table headers are visible
    cy.get('[data-testid="table-header-name"]').should('be.visible');
    cy.get('[data-testid="table-header-age"]').should('be.visible');

    // Verify table data is correct
    cy.get('[data-testid="table-row"]').first().should('contain', 'John');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Jane');

    // Print button should be visible
    cy.get('[data-testid="print-btn"]').should('be.visible');

    // Click print button
    cy.get('[data-testid="print-btn"]').click();

    // Verify print dialog appears
    cy.get('[data-testid="print-dialog"]').should('be.visible');

    // Verify print button is disabled in dialog
    cy.get('[data-testid="print-btn"]').should('be.disabled');

    // Close print dialog
    cy.get('[data-testid="print-dialog-close-btn"]').click();

    // Verify print dialog is closed
    cy.get('[data-testid="print-dialog"]').should('not.exist');
  });

  it('should handle empty table view after applying filters', () => {
    // Setup: Apply filters to table
    cy.get('[data-testid="filter-input-name"]').type('');
    cy.get('[data-testid="filter-input-age"]').type('');
    cy.get('[data-testid="apply-filters-btn"]').click();

    // Verify table is empty
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify no rows are displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');

    // Verify print button is still visible
    cy.get('[data-testid="print-btn"]').should('be.visible');

    // Click print button
    cy.get('[data-testid="print-btn"]').click();

    // Verify print dialog appears
    cy.get('[data-testid="print-dialog"]').should('be.visible');

    // Verify print button is disabled in dialog
    cy.get('[data-testid="print-btn"]').should('be.disabled');

    // Close print dialog
    cy.get('[data-testid="print-dialog-close-btn"]').click();

    // Verify print dialog is closed
    cy.get('[data-testid="print-dialog"]').should('not.exist');
  });
});
